package com.acme.reporting.controller;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.web.bind.annotation.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.thymeleaf.TemplateEngine;
import org.thymeleaf.context.Context;
import org.thymeleaf.templateresolver.StringTemplateResolver;
import javax.servlet.http.HttpServletRequest;
import java.util.Map;
import java.util.HashMap;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

@SpringBootApplication
public class ReportingApplication {
    public static void main(String[] args) {
        SpringApplication.run(ReportingApplication.class, args);
    }
}

@RestController
@RequestMapping("/api/v2/reports")
class ReportController {

    private static final Logger log = LoggerFactory.getLogger(ReportController.class);

    @Autowired
    private TemplateEngine templateEngine;

    // Internal endpoint used by partner microservices to generate custom report snippets
    // Partners provide their org-specific template fragments for branding
    @PostMapping("/render")
    public Map<String, Object> renderTemplate(
            @RequestBody ReportRequest request,
            HttpServletRequest httpRequest) {

        Map<String, Object> response = new HashMap<>();

        // Log caller info for audit trail
        String clientDN = httpRequest.getHeader("X-Forwarded-Client-Cert-DN");
        log.info("Report render request from client: {}", clientDN);

        try {
            // Validate template is not excessively large
            if (request.getTemplateFragment() != null && request.getTemplateFragment().length() > 4096) {
                response.put("error", "Template fragment exceeds maximum size");
                return response;
            }

            // Build context with safe report data
            Context context = new Context();
            context.setVariable("reportTitle", sanitizeText(request.getReportTitle()));
            context.setVariable("orgName", sanitizeText(request.getOrgName()));
            context.setVariable("generatedDate", java.time.LocalDate.now().toString());
            context.setVariable("metrics", request.getMetrics());

            // Process the partner-provided template fragment with Thymeleaf
            // This allows partners to customize report appearance
            String rendered = templateEngine.process(request.getTemplateFragment(), context);

            response.put("rendered", rendered);
            response.put("status", "success");
        } catch (Exception e) {
            log.error("Template rendering failed", e);
            response.put("error", "Rendering failed: " + e.getMessage());
            response.put("status", "error");
        }

        return response;
    }

    private String sanitizeText(String input) {
        if (input == null) return "";
        return input.replaceAll("[<>&\"']", "");
    }
}

class ReportRequest {
    private String templateFragment;
    private String reportTitle;
    private String orgName;
    private Map<String, Double> metrics;

    public String getTemplateFragment() { return templateFragment; }
    public void setTemplateFragment(String templateFragment) { this.templateFragment = templateFragment; }
    public String getReportTitle() { return reportTitle; }
    public void setReportTitle(String reportTitle) { this.reportTitle = reportTitle; }
    public String getOrgName() { return orgName; }
    public void setOrgName(String orgName) { this.orgName = orgName; }
    public Map<String, Double> getMetrics() { return metrics; }
    public void setMetrics(Map<String, Double> metrics) { this.metrics = metrics; }
}
